"""Harness hooks for the support-ops agent. H0: every hook is a pass-through.

The agent loop calls these at fixed points (see the constitution for the contract):

    user_message(prompt) -> str
    tool_description(name, description) -> str
    before_tool_call(name, args, ctx) -> str | None     # a string blocks the call and is shown to the model
    format_tool_result(name, args, text, str, is_error, ctx) -> str
    after_final(answer, ctx) -> str | None              # a string sends the model back once more
    CLIENT_TOOLS: list of {"name", "description", "parameters", "fn"}  # local, pure-Python tools

ctx = {"user_prompt": str, "step": int, "max_steps": int,
       {"calls": [{"name": str, "args": dict, "is_error": bool, "result": str}, ...]}
"""

from __future__ import annotations

import json
import re
from typing import Any

CLIENT_TOOLS: list[dict[str, Any]] = []


def user_message(prompt: str) -> str:
    return prompt


def tool_description(name: str, description: str) -> str:
    return description


def before_tool_call(name: str, args: dict[str, Any], ctx: dict[str, Any]) -> str | None:
    return None


def _truncate_value(val: Any, max_len: int = 80) -> Any:
    """Recursively truncate long strings in JSON-like structures, preserving keys."""
    if isinstance(val, str) and len(val) > max_len:
        return val[:max_len] + "..."
    elif isinstance(val, dict):
        return {k: _truncate_value(v, max_len) for k, v in val.items()}
    elif isinstance(val, list):
        return [_truncate_value(item, max_len) for item in val]
    else:
        return val


def format_tool_result(
    name: str, args: dict[str, Any], text: str, is_error: bool, ctx: dict[str, Any]
) -> str:
    # Only truncate successful, non-error results from verbose read tools
    if is_error:
        return text

    # Target tools known to produce long payloads
    if name not in ("search_kb", "list_orders", "list_tickets"):
        return text

    # Try to parse as JSON and truncate string values while keeping structure
    try:
        parsed = json.loads(text)
        truncated = _truncate_value(parsed, max_len=80)
        result = json.dumps(truncated)
        # If truncation didn't help much, return original
        if len(result) >= len(text) * 0.9:
            return text
        return result
    except (json.JSONDecodeError, TypeError):
        # Fallback: simple character truncation with ellipsis
        if len(text) > 2000:
            return text[:2000] + "\n... [truncated]"
        return text


def after_final(answer: str, ctx: dict[str, Any]) -> str | None:
    return None

